CREATE TABLE IF NOT EXISTS ${prefix}bolt_schema_version (version INT PRIMARY KEY, installed_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ${prefix}bolt_worlds (world_id VARCHAR(36) PRIMARY KEY, world_uuid VARCHAR(36) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, server_group VARCHAR(128) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, version BIGINT NOT NULL, UNIQUE KEY bolt_world_name (name, server_group));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_blocks (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, type VARCHAR(128) NOT NULL, created_at BIGINT NOT NULL, accessed_at BIGINT NOT NULL, world_id VARCHAR(36) NOT NULL, x INT NOT NULL, y INT NOT NULL, z INT NOT NULL, block VARCHAR(128) NOT NULL, version BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE KEY bolt_blocks_location (world_id, x, y, z), KEY bolt_blocks_owner (owner_id));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_entities (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, type VARCHAR(128) NOT NULL, created_at BIGINT NOT NULL, accessed_at BIGINT NOT NULL, entity VARCHAR(128) NOT NULL, version BIGINT NOT NULL, updated_at BIGINT NOT NULL, KEY bolt_entities_owner (owner_id));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_access_entries (protection_id VARCHAR(36) NOT NULL, subject_type VARCHAR(32) NOT NULL, subject_id VARCHAR(255) NOT NULL, action VARCHAR(64) NOT NULL, effect VARCHAR(16) NOT NULL, version BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (protection_id, subject_type, subject_id, action));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_groups (name VARCHAR(128) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, version BIGINT NOT NULL, KEY bolt_groups_owner (owner_id));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_group_members (group_name VARCHAR(128) NOT NULL, player_id VARCHAR(36) NOT NULL, role VARCHAR(32) NOT NULL, version BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (group_name, player_id));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_access_lists (owner_id VARCHAR(36) PRIMARY KEY, version BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ${prefix}bolt_hopper_rules (id VARCHAR(36) PRIMARY KEY, protection_id VARCHAR(36) NOT NULL, direction VARCHAR(16) NOT NULL, match_kind VARCHAR(32) NOT NULL, match_value VARCHAR(255) NOT NULL, effect VARCHAR(16) NOT NULL, priority INT NOT NULL, quantity_limit INT, version BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ${prefix}bolt_audit_events (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36), source_type VARCHAR(64) NOT NULL, source_id VARCHAR(255), action VARCHAR(64) NOT NULL, protection_id VARCHAR(36), world_id VARCHAR(36), x INT, y INT, z INT, item_type VARCHAR(128), item_amount INT, metadata TEXT, created_at BIGINT NOT NULL, KEY bolt_audit_target (protection_id, created_at));
CREATE TABLE IF NOT EXISTS ${prefix}bolt_outbox (id VARCHAR(36) PRIMARY KEY, event_type VARCHAR(64) NOT NULL, aggregate_type VARCHAR(64) NOT NULL, aggregate_id VARCHAR(255) NOT NULL, aggregate_version BIGINT NOT NULL, payload TEXT NOT NULL, published_at BIGINT, attempts INT NOT NULL, created_at BIGINT NOT NULL, KEY bolt_outbox_pending (published_at, created_at));
